H=CONFIG['hidden_size']; NL=CONFIG['num_hidden_layers']; ls=range(NL)
kinds=['mlp.down_proj','self_attn.o_proj','self_attn.v_proj','mlp.gate_proj','mlp.up_proj','self_attn.q_proj','self_attn.k_proj']
